    reset();s.activateCommand("chooseRingTool_Cyclohexane");s.gesture(PointerPhase::Down,Vec2());s.gesture(PointerPhase::Up,Vec2());s.selected=s.all();before=s.doc.digest();conformer3D();require(s.doc.digest()!=before,("3D backend: "+status).c_str());double minZ=1e9,maxZ=-1e9;for(auto& a:s.doc.atoms().records())if(a.isAlive()){auto z=s.doc.extensions(ObjectRef(ObjectKind::Atom,a.id)).findValue("studio.atom.z");require(z,"3D conformer retains per-atom depth");minZ=std::min(minZ,atof(z->c_str()));maxZ=std::max(maxZ,atof(z->c_str()));}require(maxZ-minZ>1,"cyclohexane has a non-planar 3D conformer");auto after=s.doc.digest();require(s.undo().ok()&&s.doc.digest()==before,"3D cleanup atomic undo");require(s.undo(true).ok()&&s.doc.digest()==after,"3D cleanup redo restores depths");e=s.save(testOut+"/cyclohexane_3d.cdxml",true);require(e.ok(),e.message.c_str());Session three;e=three.open(testOut+"/cyclohexane_3d.cdxml");require(e.ok(),e.message.c_str());for(auto& a:three.doc.atoms().records())if(a.isAlive())require(three.doc.extensions(ObjectRef(ObjectKind::Atom,a.id)).findValue("studio.atom.z"),"3D coordinates survive CDXML save/reopen");
